<template><div><div class="page-head"><div><h1>Student management</h1><p>Review applicant records and control account access.</p></div></div><section class="panel"><div class="toolbar"><input v-model="search" placeholder="Search name, email, applicant no." @input="delayedLoad"><select v-model="status" @change="load"><option value="">All statuses</option><option>active</option><option>suspended</option><option>archived</option></select></div><div v-if="error" class="error">{{error}}</div><div class="table-wrap"><table><thead><tr><th>Student</th><th>Applicant number</th><th>Admission year</th><th>Exam</th><th>Status</th><th>Action</th></tr></thead><tbody><tr v-for="s in page.data" :key="s.id"><td><strong>{{s.full_name}}</strong><br>{{s.email}}</td><td>{{s.student_number}}</td><td>{{s.admission_year}}</td><td>{{s.exam_taken?`${s.exam_score}/100`:'Not taken'}}</td><td><span :class="['status',s.account_status]">{{s.account_status}}</span></td><td><button class="secondary" @click="openStudent(s.id)">View</button></td></tr></tbody></table></div><div class="pagination"><button class="secondary" :disabled="!page.prev_page_url" @click="load(page.current_page-1)">Previous</button><button class="secondary" :disabled="!page.next_page_url" @click="load(page.current_page+1)">Next</button></div></section><div v-if="selected" class="modal-wrap" @click.self="selected=null"><div class="modal"><h2>{{selected.full_name}}</h2><div class="details"><p><b>Email</b>{{selected.email}}</p><p><b>Applicant number</b>{{selected.student_number}}</p><p><b>Phone</b>{{selected.phone||'Not provided'}}</p><p><b>Program match</b>{{selected.recommendation?.course?.name||'Not available'}}</p></div><div v-if="auth.canManageStudents" class="field"><label>Account status</label><select v-model="selected.account_status"><option>active</option><option>suspended</option><option>archived</option></select></div><div class="modal-actions"><button class="secondary" @click="selected=null">Close</button><button v-if="auth.canManageStudents" class="primary" @click="saveStatus">Save status</button></div></div></div></div></template>
<script setup>import{onMounted,ref}from'vue';import api,{errorMessage}from'../utils/api';import{useAdminAuth}from'../stores/auth';const auth=useAdminAuth(),page=ref({data:[]}),search=ref(''),status=ref(''),selected=ref(null),error=ref('');let timer;const load=async(p=1)=>{try{page.value=(await api.get('/admin/students',{params:{page:p,search:search.value,status:status.value}})).data}catch(e){error.value=errorMessage(e)}};const delayedLoad=()=>{clearTimeout(timer);timer=setTimeout(load,300)};const openStudent=async id=>{selected.value=(await api.get(`/admin/students/${id}`)).data.student};const saveStatus=async()=>{try{await api.patch(`/admin/students/${selected.value.id}/status`,{account_status:selected.value.account_status});selected.value=null;load()}catch(e){error.value=errorMessage(e)}};onMounted(load)</script>
<style scoped>.details{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:20px}.details p{display:flex;flex-direction:column;background:#f6f7f4;padding:12px;font-size:12px}.details b{font-size:9px;text-transform:uppercase;color:#758078;margin-bottom:4px}@media(max-width:500px){.details{grid-template-columns:1fr}}</style>
